test('returns results in input order', async () => {
  const tasks = [() => Promise.resolve(1), () => Promise.resolve(2), () => Promise.resolve(3)];
  const results = await promisePool(tasks, 2);
  expect(results).toEqual([1, 2, 3]);
});

test('runs empty array', async () => {
  const results = await promisePool([], 2);
  expect(results).toEqual([]);
});

test('concurrency of 1 runs tasks sequentially', async () => {
  const order = [];
  const tasks = [
    async () => { order.push(1); return 1; },
    async () => { order.push(2); return 2; },
  ];
  await promisePool(tasks, 1);
  expect(order).toEqual([1, 2]);
});

